@Component("exposure-handler")
@ProcessingGroup("exposure-processing-group")
public class ExposureEventHandler {
	
	// core constructor
	ExposureEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateExposureEvent
     */
    @EventHandler
    public void handle( CreateExposureEvent event) {
        entityManager.persist(new Exposure(event.getExposureId(), event.getClaim(), event.getPolicyCoverage(), event.getInsuredObject(), event.getReserves(), event.getPayments(), event.getExposureType(), event.getStatus()));
    }

    /*
     * @param	event UpdateExposureEvent
     */
    @EventHandler
    public Exposure handle( UpdateExposureEvent event) {
    	entityManager.merge(new Exposure(event.getExposureId(), event.getClaim(), event.getPolicyCoverage(), event.getInsuredObject(), event.getReserves(), event.getPayments(), event.getExposureType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteExposureEvent
     */
    @EventHandler
    public void on( DeleteExposureEvent event) {
    	Exposure entity = new Exposure();
   
    	// ------------------------------------------
    	// apply the ExposureId
    	// ------------------------------------------
    	entity.setExposureId( event.getExposureId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ExposureRepository exposureEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ExposureEventHandler.class.getName());

}
